<?php
require_once __DIR__.'/../includes/admin.php';require_role(['super_admin','admin','editor']);$pdo=db();
if(is_post()){verify_csrf();$a=$_POST['action']??'';try{if($a==='save'){$id=(int)($_POST['id']??0);$d=[trim($_POST['title_en']??''),trim($_POST['title_am']??''),trim($_POST['description_en']??''),trim($_POST['description_am']??''),trim($_POST['file_path']??''),trim($_POST['external_url']??''),($_POST['status']??'draft')==='published'?'published':'draft'];if($id){$st=$pdo->prepare('UPDATE resources SET title_en=?,title_am=?,description_en=?,description_am=?,file_path=?,external_url=?,status=? WHERE id=?');$st->execute([...$d,$id]);}else{$st=$pdo->prepare('INSERT INTO resources(title_en,title_am,description_en,description_am,file_path,external_url,status) VALUES(?,?,?,?,?,?,?)');$st->execute($d);}log_admin($id?"Updated resource #$id":'Created resource');flash('admin_success','Resource saved.');}if($a==='delete'){$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM resources WHERE id=?')->execute([$id]);log_admin("Deleted resource #$id");flash('admin_success','Resource deleted.');}}catch(Throwable $e){flash('admin_error','Resource error: '.$e->getMessage());}redirect('admin/resources.php');}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM resources WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$rows=$pdo->query('SELECT * FROM resources ORDER BY created_at DESC')->fetchAll();admin_page('Resources','resources','Add Bible notes, books, devotionals and downloadable files.');admin_flash();
?><div class="admin-panel"><h2><?= $edit?'Edit Resource':'Add Resource' ?></h2><form class="admin-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><div class="admin-form-grid"><label>Title (English)<input name="title_en" required value="<?=e($edit['title_en']??'')?>"></label><label>Title (Amharic)<input name="title_am" value="<?=e($edit['title_am']??'')?>"></label></div><div class="admin-form-grid"><label>Description (English)<textarea name="description_en" rows="4"><?=e($edit['description_en']??'')?></textarea></label><label>Description (Amharic)<textarea name="description_am" rows="4"><?=e($edit['description_am']??'')?></textarea></label></div><div class="admin-form-grid"><label>File path<input name="file_path" placeholder="assets/uploads/resources/file.pdf" value="<?=e($edit['file_path']??'')?>"></label><label>External URL<input name="external_url" value="<?=e($edit['external_url']??'')?>"></label></div><label>Status<select name="status"><option value="draft" <?=($edit['status']??'')==='draft'?'selected':''?>>Draft</option><option value="published" <?=($edit['status']??'')==='published'?'selected':''?>>Published</option></select></label><button class="btn primary">Save Resource</button></form></div><div class="admin-panel"><h2>Resource Library</h2><div class="admin-table-wrap"><table class="admin-table"><tr><th>Title</th><th>File / URL</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title_en'])?></td><td><?=e($r['file_path']?:$r['external_url']?:'—')?></td><td><span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><a class="btn small outline" href="resources.php?edit=<?=$r['id']?>">Edit</a> <form style="display:inline" method="post" onsubmit="return confirm('Delete resource?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small" style="background:var(--red);color:#fff">Delete</button></form></td></tr><?php endforeach;?></table></div></div><?php admin_end(); ?>
